// MMA2 Modbus TCP FC3 end-to-end load generator; Go standard library only.
package main
import("encoding/binary";"encoding/csv";"flag";"fmt";"io";"math";"net";"os";"path/filepath";"runtime";"sort";"strconv";"sync";"sync/atomic";"time")
type sample struct{latency time.Duration;err error}
func main(){
 addr:=flag.String("addr","127.0.0.1:15020","isolated MMA2 address");unit:=flag.Int("unit",1,"Modbus unit");clients:=flag.Int("clients",1,"concurrent clients");duration:=flag.Duration("duration",10*time.Second,"measured duration");warmup:=flag.Duration("warmup",2*time.Second,"warmup");out:=flag.String("out","benchmark/results/local","output directory");flag.Parse()
 if *clients<1||*unit<1||*unit>247||*duration<=0||*warmup<0{panic("invalid flags")};if err:=os.MkdirAll(*out,0755);err!=nil{panic(err)}
 fmt.Println("WARNING: run only against isolated test MMA2; FC3 holding register 0 quantity 1")
 run(*addr,byte(*unit),*clients,*warmup,nil)
 results:=make(chan sample,4096);var lat []float64;errors:=0;done:=make(chan struct{})
 go func(){for s:=range results{if s.err!=nil{errors++}else{lat=append(lat,float64(s.lat.Nanoseconds())/1e6)}};close(done)}()
 start:=time.Now();run(*addr,byte(*unit),*clients,*duration,results);elapsed:=time.Since(start);close(results);<-done
 sort.Float64s(lat);pct:=func(p float64)float64{if len(lat)==0{return math.NaN()};return lat[int(math.Ceil(p*float64(len(lat))))-1]};rate:=float64(len(lat))/elapsed.Seconds()
 f,e:=os.Create(filepath.Join(*out,"summary.csv"));if e!=nil{panic(e)};w:=csv.NewWriter(f);_=w.Write([]string{"target","clients","duration_seconds","successes","errors","ops_per_second","p50_ms","p95_ms","p99_ms","go_version"});_=w.Write([]string{*addr,strconv.Itoa(*clients),fmt.Sprintf("%.6f",elapsed.Seconds()),strconv.Itoa(len(lat)),strconv.Itoa(errors),fmt.Sprintf("%.3f",rate),fmt.Sprintf("%.3f",pct(.5)),fmt.Sprintf("%.3f",pct(.95)),fmt.Sprintf("%.3f",pct(.99)),runtime.Version()});w.Flush();if e=w.Error();e!=nil{panic(e)};if e=f.Close();e!=nil{panic(e)}
 f,e=os.Create(filepath.Join(*out,"latency_ms.csv"));if e!=nil{panic(e)};w=csv.NewWriter(f);_=w.Write([]string{"latency_ms"});for _,v:=range lat{_=w.Write([]string{fmt.Sprintf("%.6f",v)})};w.Flush();if e=w.Error();e!=nil{panic(e)};_=f.Close()
 svg:=fmt.Sprintf(`<svg xmlns="http://www.w3.org/2000/svg" width="640" height="260"><rect width="640" height="260" fill="white"/><text x="20" y="30" font-size="20">MMA2 Modbus TCP FC3</text><text x="20" y="70">p50: %.3f ms</text><text x="20" y="105">p95: %.3f ms</text><text x="20" y="140">p99: %.3f ms</text><text x="20" y="190">Success: %d | errors: %d</text><text x="20" y="225">Throughput: %.1f ops/s</text></svg>`,pct(.5),pct(.95),pct(.99),len(lat),errors,rate);if e=os.WriteFile(filepath.Join(*out,"summary.svg"),[]byte(svg),0644);e!=nil{panic(e)}
 fmt.Printf("success=%d errors=%d ops/s=%.1f p50=%.3fms p95=%.3fms p99=%.3fms\n",len(lat),errors,rate,pct(.5),pct(.95),pct(.99));if errors>0||len(lat)==0{os.Exit(1)}
}
func run(addr string,unit byte,clients int,d time.Duration,results chan<-sample){var wg sync.WaitGroup;var seq atomic.Uint32;deadline:=time.Now().Add(d);for i:=0;i<clients;i++{wg.Add(1);go func(){defer wg.Done();var conn net.Conn;defer func(){if conn!=nil{_=conn.Close()}}();for time.Now().Before(deadline){if conn==nil{c,e:=net.DialTimeout("tcp",addr,time.Second);if e!=nil{if results!=nil{results<-sample{err:e}};time.Sleep(10*time.Millisecond);continue};conn=c};id:=uint16(seq.Add(1));request:=[]byte{0,0,0,0,0,6,unit,3,0,0,0,1};binary.BigEndian.PutUint16(request[:2],id);_=conn.SetDeadline(time.Now().Add(time.Second));start:=time.Now();_,e:=conn.Write(request);if e==nil{head:=make([]byte,7);_,e=io.ReadFull(conn,head);if e==nil{n:=int(binary.BigEndian.Uint16(head[4:6]))-1;if n<2||n>253||binary.BigEndian.Uint16(head[:2])!=id||head[6]!=unit{e=fmt.Errorf("invalid MBAP")}else{body:=make([]byte,n);_,e=io.ReadFull(conn,body);if e==nil&&(n!=4||body[0]!=3||body[1]!=2){e=fmt.Errorf("invalid FC3 response")}}}};if results!=nil{results<-sample{latency:time.Since(start),err:e}};if e!=nil{_=conn.Close();conn=nil}}}()};wg.Wait()}
